1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE = 0.1;
3	const CURSE_SURCHARGE = 0.5;
4	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
5	const HIGH_ENCHANTMENT_LEVEL = 5;
6	const LOYALTY_DISCOUNT = 0.2;
7	const LOYALTY_YEARS = 2;
8	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
9	
10	const BASE_PREMIUMS: Record<string, number> = {
11	  sword: 100,
12	  amulet: 60,
13	  staff: 80,
14	  potion: 40,
15	  rune: 25,
16	  moonstone: 25,
17	};
18	
19	const INSURANCE_VALUES: Record<string, number> = {
20	  sword: 1000,
21	  amulet: 600,
22	  staff: 800,
23	  potion: 400,
24	  rune: 250,
25	  moonstone: 250,
26	};
27	
28	const DEDUCTIBLE = 100;
29	const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
30	const HIGH_ENCHANTMENT_REIMBURSEMENT = 0.5;
31	const CAP_MULTIPLIER = 2;
32	
33	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
34	const BLOCK_SIZE = 3;
35	const BLOCK_BASE_PREMIUM = 60;
36	
37	export interface Customer {
38	  yearsWithMHPCO: number;
39	}
40	
41	export interface Scenario {
42	  customer: Customer;
43	  steps: Step[];
44	}
45	
46	export interface QuoteStep {
47	  op: "quote";
48	  items: Item[];
49	}
50	
51	export interface Item {
52	  type: string;
53	  material?: string;
54	  enchantment?: number;
55	  cursed?: boolean;
56	}
57	
58	export interface Damage {
59	  itemType: string;
60	  amount: number;
61	}
62	
63	export interface ClaimStep {
64	  op: "claim";
65	  policy: number;
66	  incident: {
67	    cause: string;
68	    damages: Damage[];
69	  };
70	}
71	
72	export type Step = QuoteStep | ClaimStep;
73	
74	export interface QuoteResult {
75	  premium: number;
76	}
77	
78	export interface ClaimResult {
79	  payout: number;
80	  remainingCap: number;
81	}
82	
83	export type StepResult = QuoteResult | ClaimResult;
84	
85	export interface ScenarioResult {
86	  results: StepResult[];
87	}
88	
89	/**
90	 * The base premium of a whole item list. Components are priced per type,
91	 * because a building block is only offered for a group of exactly
92	 * BLOCK_SIZE alike components; any other count is charged individually.
93	 */
94	function policyBasePremium(items: Item[]): number {
95	  let total = 0;
96	  const componentCounts = new Map<string, number>();
97	
98	  for (const item of items) {
99	    if (!(item.type in BASE_PREMIUMS)) {
100	      throw new ScenarioError(`unknown item type: ${item.type}`);
101	    }
102	    if (COMPONENT_TYPES.has(item.type)) {
103	      componentCounts.set(item.type, (componentCounts.get(item.type) ?? 0) + 1);
104	    } else {
105	      total += BASE_PREMIUMS[item.type];
106	    }
107	  }
108	
109	  for (const [type, count] of componentCounts) {
110	    total +=
111	      count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
112	  }
113	
114	  return total;
115	}
116	
117	function itemSurcharge(item: Item): number {
118	  const base = BASE_PREMIUMS[item.type];
119	  let surcharge = 0;
120	
121	  if (item.cursed) {
122	    surcharge += base * CURSE_SURCHARGE;
123	  }
124	  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL) {
125	    surcharge += base * HIGH_ENCHANTMENT_SURCHARGE;
126	  }
127	
128	  return surcharge;
129	}
130	
131	function quote(
132	  step: QuoteStep,
133	  customer: Customer,
134	  previousContracts: number,
135	): QuoteResult {
136	  const policyBase = policyBasePremium(step.items);
137	
138	  const itemSurcharges = step.items.reduce(
139	    (sum, item) => sum + itemSurcharge(item),
140	    0,
141	  );
142	
143	  let policyAdjustments = policyBase * FIRST_INSURANCE_SURCHARGE;
144	
145	  if (customer.yearsWithMHPCO >= LOYALTY_YEARS) {
146	    policyAdjustments -= policyBase * LOYALTY_DISCOUNT;
147	  }
148	  if (previousContracts > 0) {
149	    policyAdjustments -= policyBase * FOLLOW_UP_CONTRACT_DISCOUNT;
150	  }
151	
152	  const premium =
153	    policyBase + itemSurcharges + policyAdjustments + PROCESSING_FEE;
154	
155	  return { premium: Math.ceil(premium) };
156	}
157	
158	interface Policy {
159	  items: Item[];
160	  remainingCap: number;
161	}
162	
163	/**
164	 * The reimbursable share of a damage amount, before the deductible.
165	 *
166	 * Dragon material is reimbursed in full, which is also the ordinary
167	 * treatment, so it needs no branch of its own. The high-enchantment clause
168	 * takes precedence over it: when an item is both dragon-made and highly
169	 * enchanted, the 50% rule wins.
170	 */
171	function reimbursement(item: Item, amount: number): number {
172	  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL) {
173	    return amount * HIGH_ENCHANTMENT_REIMBURSEMENT;
174	  }
175	  return amount;
176	}
177	
178	function claim(step: ClaimStep, policy: Policy): ClaimResult {
179	  const available = [...policy.items];
180	
181	  const desired = step.incident.damages.reduce((sum, damage) => {
182	    if (damage.amount < 0) {
183	      throw new ScenarioError(
184	        `damage amount cannot be negative: ${damage.amount}`,
185	      );
186	    }
187	
188	    const index = available.findIndex((item) => item.type === damage.itemType);
189	    if (index === -1) {
190	      throw new ScenarioError(
191	        `the policy does not cover a damaged ${damage.itemType}`,
192	      );
193	    }
194	
195	    const [item] = available.splice(index, 1);
196	    return sum + Math.max(0, reimbursement(item, damage.amount) - DEDUCTIBLE);
197	  }, 0);
198	
199	  const payout = Math.floor(Math.min(desired, policy.remainingCap));
200	  policy.remainingCap -= payout;
201	
202	  return { payout, remainingCap: policy.remainingCap };
203	}
204	
205	/** A scenario the MHPCO declines to process. */
206	export class ScenarioError extends Error {}
207	
208	export function runScenario(scenario: Scenario): ScenarioResult {
209	  let contracts = 0;
210	  const policies = new Map<number, Policy>();
211	
212	  const results = scenario.steps.map((step, index) => {
213	    if (step.op === "claim") {
214	      const policy = policies.get(step.policy);
215	      if (!policy) {
216	        throw new ScenarioError(
217	          `step ${step.policy} did not create a policy to claim against`,
218	        );
219	      }
220	      return claim(step, policy);
221	    }
222	
223	    const result = quote(step, scenario.customer, contracts);
224	    contracts += 1;
225	    policies.set(index, {
226	      items: step.items,
227	      remainingCap:
228	        step.items.reduce(
229	          (sum, item) => sum + INSURANCE_VALUES[item.type],
230	          0,
231	        ) * CAP_MULTIPLIER,
232	    });
233	    return result;
234	  });
235	
236	  return { results };
237	}
