1	#!/usr/bin/env node
2	import { runScenario, type Scenario } from "./scenario.js";
3	
4	async function readStdin(): Promise<string> {
5	  const chunks: Uint8Array[] = [];
6	  for await (const chunk of process.stdin) {
7	    chunks.push(chunk);
8	  }
9	  return Buffer.concat(chunks).toString("utf8");
10	}
11	
12	async function main(): Promise<void> {
13	  const input = await readStdin();
14	
15	  let scenario: Scenario;
16	  try {
17	    scenario = JSON.parse(input) as Scenario;
18	  } catch (error) {
19	    throw new Error(`input is not valid JSON: ${(error as Error).message}`);
20	  }
21	
22	  process.stdout.write(JSON.stringify(runScenario(scenario)) + "\n");
23	}
24	
25	main().catch((error: Error) => {
26	  process.stderr.write(`claim-office: ${error.message}\n`);
27	  process.exitCode = 1;
28	});
