7	interface Run {
8	  stdout: string;
9	  stderr: string;
10	  code: number;
11	}
12	
13	/** Runs the claim-office CLI with the given stdin, as a user would. */
14	const runCli = (input: string): Promise<Run> =>
15	  new Promise((resolve) => {
16	    const child = execFile(
17	      "npx",
18	      ["tsx", CLI],
19	      (error, stdout, stderr) => {
20	        resolve({
21	          stdout,
22	          stderr,
23	          code: error && typeof error.code === "number" ? error.code : 0,
24	        });
25	      },
26	    );
27	    child.stdin!.end(input);
28	  });
